List<List<Integer>> g = new ArrayList<>();
for (int i = 0; i < 4; i++) g.add(new ArrayList<>());
g.get(0).add(1);
g.get(1).add(0);
g.get(1).add(2);
System.out.println(g.get(1));

// Graph: 1-2, 1-3, 2-4, 3-4 (lists built above: g[1]=[2,3], g[2]=[1,4], g[3]=[1,4], g[4]=[2,3])
boolean[] vis = new boolean[5];
Queue<Integer> q = new ArrayDeque<>();
q.offer(1); vis[1] = true;
while (!q.isEmpty()) {
    int u = q.poll();
    System.out.print(u);
    for (int v : g.get(u)) if (!vis[v]) { vis[v] = true; q.offer(v); }
}

// Graph: 1-2, 2-3, 1-4 (lists built above: g[1]=[2,4], g[2]=[1,3], g[3]=[2], g[4]=[1])
int[] dist = new int[5];
Arrays.fill(dist, -1);
dist[1] = 0;
Queue<Integer> q = new ArrayDeque<>();
q.offer(1);
while (!q.isEmpty()) {
    int u = q.poll();
    for (int v : g.get(u)) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.offer(v); }
}
System.out.println(dist[3] + " " + dist[4]);

// g[1]=[2,3], g[2]=[1,3], g[3]=[1,2]  (triangle built above)
